function [b] = field_eci_at(lat, lon, h, c, gh, nmax)
%FIELD_ECI_AT  The field in J2000 [T, as plain numbers] at geodetic latitude, longitude [rad] and height, given the J2000 to
%   Earth-fixed matrix and the Gauss coefficients at the date, to degree nmax.
%   lat: real[1] (passed a plain number)
%   lon: real[1] (passed a plain number)
%   h: real[m] (passed in m)
%   c: real[1][3][3] (passed a plain number)
%   gh: real[1][195] (passed a plain number)
%   nmax: int (passed a whole number)
%   returns b: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    b = zeros(3, 1);
    bn = (asils.models.frames.igrf_ned(gh, lat, lon, (h / 1000), nmax) * 1e-9);
    sl = sin(lat);
    cl = cos(lat);
    so = sin(lon);
    co = cos(lon);
    be = [(((((-(sl)) * co) * bn(1)) - (so * bn(2))) - ((cl * co) * bn(3))); (((((-(sl)) * so) * bn(1)) + (co * bn(2))) - ((cl * so) * bn(3))); ((cl * bn(1)) - (sl * bn(3)))];
    b = asils.pc.mv((c).', be);
end
